/* Staff & payroll: profiles (staff ledgers), attendance, payroll run → salary entries, payslips, NEFT sheet, advances, notebook, celebrations */
(()=>{
const J=window.J,{S,esc,inr,r2,money,money0,fmtDate,today,addDays,uid,fld,txt,num,dateI,selO,area,toast,monthLabel,daysInMonth,pad}=J;
const ui=()=>J.ui("staff",{month:today().slice(0,7),attDate:today(),tag:"",q:"",pmonth:""});
const DOW=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
// one working month shared by every Staff tab (attendance, employee month, payroll, advances, notebook)
const WM=()=>{const U=ui();if(!U.wm)U.wm=today().slice(0,7);return U.wm};J.staffMonth=WM;
const inMonth=(s,m)=>J.H.stints(s).length?J.H.inServiceRange(s,m+"-01",J.monthEnd(m)):s.active!==false;J.staffInMonth=(m)=>staff(true).filter(s=>inMonth(s,m));
// staff picker for a month: only people in service at some point that month (plus the one already chosen)
const staffSel=(n,sel,m)=>{const list=J.staffInMonth(m);const cur=sel&&J.get("accounts",sel);if(cur&&!list.some(x=>x.id===sel))list.push(cur);return `<select name="${n}" id="f-${n}"><option value="">Choose staff…</option>${list.sort((a,b)=>(a.code||"").localeCompare(b.code||"")).map(x=>`<option value="${x.id}" ${x.id===sel?"selected":""}>${esc((x.code?x.code+" · ":"")+x.name)}${x.active===false?" (left)":""}</option>`).join("")}</select><p class="hint" style="margin:2px 0 0">Staff in service in ${monthLabel(m)}.</p>`};J.staffSel=staffSel;
const ST={P:"Present",H:"Half-day",A:"Absent",L:"Paid leave",W:"Week off",WW:"Worked on week off",O:"Not scheduled (service terms)"};
const staff=(all)=>J.all("accounts").filter(a=>a.kind==="staff"&&(all||a.active!==false)).sort((a,b)=>a.name.localeCompare(b.name));
J.staffList=staff;
const att=m=>J.get("attendance",m)?.days||{};
const dayStatus=(sid,date)=>{const d=att(date.slice(0,7))[String(+date.slice(8))]?.[sid];return d};
const weekOff=(s,date)=>J.R.isWeekOff(s,date);
const toMin=t=>{if(!t)return null;const [h,m]=t.split(":").map(Number);return h*60+(m||0)};
const lateMins=(s,rec)=>J.R.lateMin(s,rec);
const PT_WB=g=>g<=10000?0:g<=15000?110:g<=25000?130:g<=40000?150:200;

// ---------- celebrations ----------
function upcoming(days=30){const t=today(),out=[];const yr=+t.slice(0,4);
  const push=(s,md,kind,yrs)=>{for(const y of [yr,yr+1]){const d=y+"-"+md;const n=J.daysBetween(t,d);if(n>=0&&n<=days){out.push({s,date:d,n,kind,yrs:yrs!=null?y-yrs:null});break}}};
  for(const s of staff()){if(s.dob)push(s,s.dob.slice(5),"Birthday",+s.dob.slice(0,4));if(s.doj)push(s,s.doj.slice(5),"Work anniversary",+s.doj.slice(0,4))}
  for(const c of J.all("contacts"))if(c.dob)push({name:c.name,id:"c:"+c.id},c.dob.slice(5),"Birthday (directory)",null);
  return out.filter(x=>x.kind!=="Work anniversary"||x.yrs>0).sort((a,b)=>a.n-b.n)}
J.upcomingCelebrations=upcoming;

// ---------- Staff master ----------
function vStaff(){const U=ui();const HH=J.H;const show=U.show||"active";const q=(U.q||"").toLowerCase();
  const all=staff(true);const list=all.filter(s=>(show==="all"||(show==="month"?inMonth(s,WM()):(show==="active")===(s.active!==false)))&&(!q||(s.name+" "+(s.code||"")+" "+(s.desig||"")+" "+(s.dept||"")+" "+(s.phone||"")).toLowerCase().includes(q))).sort((a,b)=>(a.baseCode||"~").localeCompare(b.baseCode||"~")||a.name.localeCompare(b.name));
  const cel=upcoming(30);const t=today();const nA=all.filter(s=>s.active!==false).length;
  const head=`${cel.length?`<section class="panel"><h2>Celebrations · next 30 days</h2><div class="pb row" style="gap:10px">${cel.map(c=>`<span class="chip ${c.n===0?"ok":"plain"}" style="font-size:12.5px;padding:4px 10px">${c.n===0?"Today":c.n===1?"Tomorrow":fmtDate(c.date)} · ${esc(c.s.name)} · ${c.kind}${c.yrs?" ("+c.yrs+(c.kind==="Birthday"?"":" yr")+")":""}</span>`).join("")}</div></section>`:""}
  <div class="filters"><div class="seg">${[["active","Active ("+nA+")"],["former","Former ("+(all.length-nA)+")"],["all","All ("+all.length+")"],["month","In "+monthLabel(WM())+" ("+all.filter(x=>inMonth(x,WM())).length+")"]].map(([k,l])=>`<button data-set="staff.show=${k}" aria-pressed="${show===k}">${l}</button>`).join("")}</div><div class="seg">${[["cards","Cards"],["roster","Master roster"]].map(([k,l])=>`<button data-set="staff.view=${k}" aria-pressed="${(U.view||"cards")===k}">${l}</button>`).join("")}</div>
    ${fld("Search",`<input id="sf-q" data-ui="staff.q" value="${esc(U.q||"")}" placeholder="Name, code, role, phone">`)}<div class="row" style="margin-left:auto"><button class="btn w" data-a="openStaffWb">Import staff workbook</button><button class="btn" data-a="rosterCsv">Export roster</button><button class="btn primary w" data-a="newStaff">Add staff member</button></div></div>`;
  if(!list.length)return head+`<div class="panel"><div class="empty"><strong>${all.length?"No one matches":"No staff yet"}</strong><span>${all.length?"Change the filter or search.":"Add staff one by one, or import your staff workbook to bring in everyone with their joinings, rejoinings, increments and exits."}</span></div></div>`;
  if((U.view||"cards")==="roster")return head+`<div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Code</th><th>Name</th><th>Role</th><th>Status</th><th>1st joining</th><th>Current stint</th><th>Exit / LWD</th><th class="num">Stints</th><th class="num">Days served</th><th>Service</th><th class="num">Incr.</th><th class="num">Gross</th><th class="num">CTC</th><th>Phone</th></tr></thead><tbody>
    ${list.map(s=>{const sm=HH.summary(s);return `<tr><td class="mono"><button class="linkbtn" data-a="staffProfile" data-x="${s.id}"><b>${esc(sm.code||s.code||"—")}</b></button></td><td>${esc(s.name)}</td><td>${esc([s.desig,s.dept].filter(Boolean).join(" · "))}</td><td>${sm.active?'<span class="chip ok">Active</span>':'<span class="chip plain">Relieved</span>'}</td><td>${fmtDate(sm.first?.join||s.doj)}</td><td>${fmtDate(sm.cur?.join)}</td><td>${sm.lwd?fmtDate(sm.lwd):"—"}</td><td class="num">${sm.count||""}</td><td class="num">${sm.served||""}</td><td>${esc(sm.servedText||"")}</td><td class="num">${sm.increments||""}</td><td class="num">${money0(sm.gross||s.sal?.gross||0)}</td><td class="num">${money0((sm.gross||s.sal?.gross||0)*12)}</td><td class="mono">${esc(s.phone||"")}</td></tr>`}).join("")}</tbody></table></div></div>`;
  return head+`<div class="cards">${list.map(s=>{const b=J.balanceOf(s.id);const today_=dayStatus(s.id,t);const sm=HH.summary(s);return `<button class="card" data-a="staffProfile" data-x="${s.id}"><div class="row" style="gap:10px;flex-wrap:nowrap"><span class="avatar">${s.img?`<img src="${esc(s.img)}" alt="">`:esc(J.initials(s.name))}</span><div style="min-width:0"><h3>${esc(s.name)}</h3><div class="muted" style="font-size:12.5px"><span class="mono">${esc(sm.code||s.code||"")}</span>${sm.code?" · ":""}${esc([s.desig,s.dept].filter(Boolean).join(" · ")||"—")}</div></div></div>
    <dl class="kv"><dt>Service</dt><dd>${sm.count?(sm.active?"Since "+fmtDate(sm.cur.join):"Left "+fmtDate(sm.lwd))+(sm.count>1?` · ${sm.count} stints`:""):"—"}</dd><dt>Monthly salary</dt><dd>${money0(sm.gross||s.sal?.gross||0)}</dd><dt>Ledger</dt><dd>${b>0.004?`<span class="chip warn">Advance ${money0(b)}</span>`:b<-0.004?`<span class="chip bad">Due ${money0(-b)}</span>`:"Settled"}</dd>${s.active!==false?`<dt>Today</dt><dd>${today_?`<span class="chip ${today_.s==="A"?"bad":today_.s==="H"?"warn":"ok"}">${ST[today_.s]}${lateMins(s,today_)?" · late "+lateMins(s,today_)+"m":""}</span>`:weekOff(s,t)?'<span class="chip plain">Week off</span>':'<span class="muted">Not marked</span>'}</dd>`:""}</dl></button>`}).join("")}</div>`}
J.act("openStaffWb",()=>J.openStaffWorkbook());
function staffDrawer(id){const s=id?J.get("accounts",id):{kind:"staff",active:true,sal:{weekOff:"",start:"10:00",pt:true}};const sal=s.sal||{};const hist=id&&J.H.stints(s).length>0&&(Array.isArray(s.stints)&&s.stints.length);
  const code=id?(s.code||s.baseCode||""):J.H.nextBase();const ch=(n,l,v)=>`<label class="row" style="gap:6px"><input type="checkbox" name="${n}" id="f-${n}" ${v?"checked":""}> ${l}</label>`;
  J.drawer({title:id?"Edit "+s.name:"Add staff member",wide:true,submit:"Save",body:`<div class="row" style="gap:12px;align-items:center"><span class="avatar" id="imgPrev" style="width:56px;height:56px">${s.img?`<img src="${esc(s.img)}" alt="">`:esc(J.initials(s.name||"?"))}</span><label class="f">Photo<input type="file" id="f-img" accept="image/*" data-ach="pickImg"></label><input type="hidden" name="img" id="f-imgdata" value="${esc(s.img||"")}"><span class="chip plain mono" style="margin-left:auto">${esc(code)}</span></div>
    <div class="form">${fld("Full name",txt("name",s.name,"","required"))}${fld("Designation",txt("desig",s.desig,"Cook, Captain, Helper…"))}${fld("Department",`<input name="dept" id="f-dept" list="deptlist" value="${esc(s.dept||"")}"><datalist id="deptlist">${[...new Set(["Kitchen (Main / Curry)","Tandoor & Grill","Service (Captains & Stewards)","Cashier & Billing","Housekeeping & Utility","Restaurant Management","Owner",...staff(true).map(x=>x.dept).filter(Boolean)])].map(d=>`<option value="${esc(d)}">`).join("")}</datalist>`)}
      ${hist?"":fld("Joining date",dateI("doj",s.doj||today()))+fld("Monthly gross (₹)",num("gross",sal.gross))}</div>
    ${hist?`<p class="hint" style="margin:0">Joining, exit and salary come from the employment history. Use Record exit, Rejoin or Salary revision on the profile to change them.</p>`:""}
    <h3 class="ph" style="padding:6px 0 0">Contact</h3><div class="form">${fld("Primary phone",txt("phone",s.phone))}${fld("Secondary phone",txt("phone2",s.phone2))}${fld("Alternate contact",txt("altContact",s.altContact))}${fld("Emergency contact",txt("emergency",s.emergency))}${fld("Email",txt("email",s.email))}${fld("Date of birth",dateI("dob",s.dob))}${fld("Anniversary",dateI("anniv",s.anniv))}${fld("Father's name",txt("father",s.father))}${fld("Mother's name",txt("mother",s.mother))}</div>
    ${fld("Current address",area("address",s.address,2))}${fld("Permanent address",area("permAddress",s.permAddress,2))}${fld("Google Maps link",txt("mapLink",s.mapLink))}
    <h3 class="ph" style="padding:6px 0 0">Identity &amp; bank</h3><div class="form">${fld("Aadhaar",txt("aadhaar",s.aadhaar))}${fld("PAN",txt("pan",s.pan))}${fld("Voter ID",txt("voter",s.voter))}${fld("Ration card",txt("ration",s.ration))}${fld("Driving licence",txt("dl",s.dl))}${fld("Bank name",txt("bankName",s.bankName))}${fld("Account no.",txt("bankAc",s.bankAc))}${fld("Branch",txt("branch",s.branch))}${fld("IFSC",txt("ifsc",s.ifsc))}${fld("UPI ID",txt("upi",s.upi))}</div>
    <h3 class="ph" style="padding:6px 0 0">Shift &amp; attendance</h3><div class="form">${fld("Weekly off",selO("weekOff",DOW.map((d,i)=>[String(i),d]),sal.weekOff,"None"))}${fld("Shift",selO("shift",[["","Custom timings below"],...Object.entries(J.R.rules().shifts).map(([k,x])=>[k,x.label+" · "+x.segs.map(y=>y.join("–")).join(", ")])],sal.shift||""))}${fld("Shift start",`<input type="time" name="start" id="f-start" value="${esc(sal.start||"10:00")}">`)}${fld("Shift end",`<input type="time" name="end" id="f-end" value="${esc(sal.end||"")}">`)}${fld("Rest break",txt("rest",sal.rest,"15:00-16:00"))}${fld("Tracking mode",selO("tracking",["TIME BOUND","FLEXIBLE HOURS","PART TIME_WEEKLY","MANAGEMENT EXEMPT"],s.tracking||"TIME BOUND"))}${fld("Salary basis",selO("basis",[["calendar_days","Calendar days in month"],["30_days","30-day month"]],sal.basis||"calendar_days"))}</div>
    <h3 class="ph" style="padding:6px 0 0">Service terms</h3><div class="row" style="gap:16px;flex-wrap:wrap">${ch("tfixed","Fixed monthly salary (attendance never changes pay)",s.terms?.fixed)}${ch("tauto","Mark attendance automatically every day",s.terms?.auto)}</div>
    <div class="row" style="gap:12px;flex-wrap:wrap"><span class="hint">Attends on:</span>${DOW.map((d,i)=>ch("td"+i,d,(s.terms?.days||[0,1,2,3,4,5,6]).includes(i))).join("")}</div><p class="hint" style="margin:0">With automatic marking, each scheduled day is marked Present (Week off on the weekly off) and the other days "Not scheduled", from the joining date onwards. Days you change by hand are kept.</p>
    <div class="row" style="gap:16px">${ch("exempt","No salary cut for absence",sal.exempt||s.salaryCutExempt)}${ch("mgmt","Management",s.mgmt)}${ch("noLeave","No leave basis",s.noLeave)}</div>
    <h3 class="ph" style="padding:6px 0 0">Salary structure &amp; deductions</h3><div class="form">${fld("Basic",num("basic",sal.basic,"for PF"))}${fld("HRA",num("hra",sal.hra))}${fld("DA",num("da",sal.da))}${fld("TDS per month",num("tds",sal.tds,"0"))}${fld("Advance recovery per month",num("instal",sal.instal,"full balance"))}${fld("Loan EMI per month",num("loanEmi",sal.loanEmi,"0"))}</div>
    <div class="row" style="gap:16px">${ch("pf","PF (12%)",sal.pf)}${ch("esic","ESIC (0.75%)",sal.esic)}${ch("pt","Professional tax (WB)",sal.pt!==false)}</div>
    <p class="hint">Per-day rate is monthly gross ÷ days in the month (or ÷ 30 on a 30-day basis). Working on the weekly off pays double. Late, overtime and weekly-off eligibility follow Staff → Policies &amp; rules.</p>`,
    onSubmit:async fd=>{const name=fd.name.trim();if(!name)return "Enter the name.";if(J.all("accounts").some(x=>x.id!==id&&x.name.toLowerCase()===name.toLowerCase()))return "A ledger with this name already exists.";
      const keep=["phone","phone2","altContact","emergency","email","dob","anniv","father","mother","address","permAddress","mapLink","aadhaar","voter","ration","dl","bankName","bankAc","branch","upi"];const n={...(id?s:{opening:0,notes:[]}),id:id||"staff-"+code.toLowerCase(),name,kind:"staff",desig:fd.desig,dept:fd.dept,img:fd.img,pan:fd.pan.toUpperCase(),ifsc:fd.ifsc.toUpperCase(),tracking:fd.tracking,mgmt:fd.mgmt,noLeave:fd.noLeave,salaryCutExempt:fd.exempt};for(const k of keep)n[k]=(fd[k]||"").trim();
      n.sal={...sal,basic:+fd.basic||0,hra:+fd.hra||0,da:+fd.da||0,tds:+fd.tds||0,instal:fd.instal===""?"":+fd.instal,loanEmi:+fd.loanEmi||0,weekOff:fd.weekOff,shift:fd.shift||"",start:fd.shift?J.R.rules().shifts[fd.shift].segs[0][0]:fd.start,end:fd.end,rest:fd.rest,basis:fd.basis,exempt:fd.exempt,pf:fd.pf,esic:fd.esic,pt:fd.pt};
      if(!hist){if(!fd.doj)return "Enter the joining date.";const g=+fd.gross||0;n.baseCode=s.baseCode||code;n.stints=[{join:fd.doj,exit:"",desig:fd.desig,dept:fd.dept,startSal:g,endSal:g}];n.revisions=[{date:fd.doj,kind:"join",event:"Starting salary",from:0,to:g,desig:fd.desig,reason:"Initial appointment",seq:1}]}
      else{const st=J.H.stints(s);st[st.length-1]={...st[st.length-1],desig:fd.desig,dept:fd.dept};n.stints=st}
      const days=DOW.map((_,i)=>i).filter(i=>fd["td"+i]);n.terms={fixed:!!fd.tfixed,auto:!!fd.tauto,days:days.length?days:[0,1,2,3,4,5,6]};if(n.terms.fixed){n.sal.exempt=true;n.salaryCutExempt=true}
      const before=JSON.stringify(s.terms||{});await J.store.put("accounts",J.H.sync(n));await J.staffSubAcc(n.id,"adv");await J.staffSubAcc(n.id,"loan");toast("Saved "+name);if(id&&before!==JSON.stringify(n.terms)&&n.terms.auto){const c=await J.H.fillAttendance(today(),[n.id],true);if(c)toast(c+" days re-marked to the service terms");J.H.syncSoon("service terms changed for "+name)}}})}
J.act("newStaff",()=>staffDrawer(null));J.act("editStaff",el=>{J.closeDrawer();staffDrawer(el.dataset.x)});
J.act("staffProfile",el=>{const s=J.get("accounts",el.dataset.x);const b=J.balanceOf(s.id);const notes=(Array.isArray(s.notes)?s.notes:[]).slice().reverse();const act=s.active!==false;
  J.drawer({title:s.name,wide:true,body:`<div class="row" style="gap:12px"><span class="avatar" style="width:64px;height:64px;font-size:20px">${s.img?`<img src="${esc(s.img)}" alt="">`:esc(J.initials(s.name))}</span><div><div><b class="mono">${esc(s.code||"")}</b> ${esc([s.desig,s.dept].filter(Boolean).join(" · "))}</div><div>${b>0.004?`Advance outstanding ${money(b)}`:b<-0.004?`Salary due ${money(-b)}`:"Ledger settled"}</div></div></div>
    <div class="row"><button type="button" class="btn w" data-a="editStaff" data-x="${s.id}">Edit profile</button>${act?`<button type="button" class="btn w" data-a="staffIncrement" data-x="${s.id}">Salary revision</button><button type="button" class="btn w" data-a="staffExit" data-x="${s.id}">Record exit</button><button type="button" class="btn w" data-a="giveAdv" data-x="${s.id}">Give advance</button>`:`<button type="button" class="btn primary w" data-a="staffRejoin" data-x="${s.id}">Rejoin as ${esc(J.H.codeFor(s.baseCode||s.code||"",J.H.stints(s).length))}</button>`}<button type="button" class="btn" data-a="empAtt" data-x="${s.id}">Attendance</button><button type="button" class="btn" data-a="openLedger" data-x="${s.id}">Ledger</button><button type="button" class="btn w" data-a="addNote" data-x="${s.id}">Add note</button></div>
    ${J.H.historyHtml(s)}
    <h3 class="ph" style="padding:8px 0 0">Personal, shift &amp; bank</h3>${J.H.personalHtml(s)}
    <dl class="kv"><dt>Salary structure</dt><dd>Basic ${money0(s.sal?.basic||0)} · HRA ${money0(s.sal?.hra||0)} · DA ${money0(s.sal?.da||0)}</dd><dt>Statutory</dt><dd>${[s.sal?.pf&&"PF",s.sal?.esic&&"ESIC",s.sal?.pt!==false&&"PT",s.sal?.tds&&("TDS "+money0(s.sal.tds))].filter(Boolean).join(", ")||"None"}</dd></dl>
    <h3 class="ph" style="padding:8px 0 0">Notebook</h3><div class="timeline">${notes.map(n=>`<div class="ti"><span class="chip plain">${esc(n.tag)}</span> <small>${fmtDate(n.date)}${n.by?" · "+esc(n.by):""}</small><div>${esc(n.text)}</div></div>`).join("")||'<p class="muted">No notes yet.</p>'}</div>`});
  document.querySelectorAll("#drawerForm [data-a]").forEach(b=>b.addEventListener("click",()=>{if(!["addNote","staffExit","staffRejoin","staffIncrement","stintEdit","editStaff","revDel","stintDel"].includes(b.dataset.a))J.closeDrawer()},{capture:true}))});
J.act("giveAdv",async el=>{const sid=el.dataset.x;J.closeDrawer();await J.staffSubAcc(sid,"adv");J.newEntry("advance",{staff:sid,date:entryDay()})});
J.act("giveLoan",async el=>{const sid=el.dataset.x;J.closeDrawer();await J.staffSubAcc(sid,"loan");J.newEntry("staffloan",{staff:sid,date:entryDay()})});
const entryDay=()=>{const m=WM();const t=today();return m===t.slice(0,7)?t:m<t.slice(0,7)?J.monthEnd(m):m+"-01"};

// ---------- Attendance ----------
function vAttendance(){const U=ui();if(!U.attDate||U.attDate.slice(0,7)!==WM())U.attDate=WM()===today().slice(0,7)?today():WM()+"-01";const d=U.attDate;const m=d.slice(0,7),day=String(+d.slice(8));const recs=att(m)[day]||{};const list=staff(true).filter(s=>J.H.stints(s).length?J.H.inService(s,d):s.active!==false);
  const counts={};for(const s of list){const r=recs[s.id];const k=r?.s||(weekOff(s,d)?"W":"—");counts[k]=(counts[k]||0)+1}
  return `<div class="filters">${fld("Date",`<input type="date" id="at-date" data-ach="attDay" value="${d}">`)}<span class="muted">${DOW[J.parseISO(d).getDay()]}</span>
    <div class="row" style="margin-left:auto">${Object.entries(counts).map(([k,n])=>`<span class="chip ${k==="P"||k==="WW"?"ok":k==="A"?"bad":k==="H"?"warn":"plain"}">${k==="—"?"Unmarked":ST[k]} ${n}</span>`).join("")}<button class="btn w" data-a="fillAtt" title="Marks every unmarked day inside each person's tenure as Present (Week off on their weekly off)">Fill tenure attendance</button><button class="btn w" data-a="allPresent">Mark all unmarked present</button><button class="btn w" data-a="attImport">Upload month CSV</button></div></div>
  <div class="panel"><div class="tbl-wrap"><table class="att"><thead><tr><th style="text-align:left">Staff</th><th>Status</th><th>In</th><th>Out</th><th>In (2)</th><th>Out (2)</th><th>Shift start today</th><th>Worked</th><th>Late</th><th>OT hrs</th></tr></thead><tbody>
  ${list.length?list.map(s=>punchRow(s,d,recs[s.id]||{},"")).join(""):J.emptyRow(10,"No active staff","Add staff members first.")}
  </tbody></table></div></div><p class="hint">Changes save as you make them. For a split shift enter both spells (In/Out and In (2)/Out (2)); with a single In and Out the scheduled rest break is left out. Lateness is measured from the shift start (or the start you set for the day) to the first punch-in; overtime is time worked beyond ${J.R.rules().otAfter} hours. Type OT hours only to override the automatic figure.</p>
  ${matrix(m,J.staffInMonth(m))}`}
function matrix(m,list){const D=daysInMonth(m);const days=att(m);
  return `<section class="panel"><h2>${monthLabel(m)} attendance matrix</h2><div class="tbl-wrap"><table class="mx"><thead><tr><th style="text-align:left">Staff</th>${[...Array(D)].map((_,i)=>`<th style="padding:3px 2px;text-align:center">${i+1}</th>`).join("")}<th>P</th><th>A</th><th>Late</th></tr></thead><tbody>
  ${list.map(s=>{let P=0,A=0,L=0;const cells=[...Array(D)].map((_,i)=>{const date=m+"-"+pad(i+1);const r=days[String(i+1)]?.[s.id];const k=r?.s||(weekOff(s,date)?"W":"");if(k==="P"||k==="WW")P++;if(k==="H")P+=0.5;if(k==="A")A++;if(lateMins(s,r))L++;return `<td class="st-${k}" title="${date} ${ST[k]||"unmarked"}">${k==="WW"?"2×":k==="O"?"–":k||"·"}</td>`}).join("");return `<tr><td style="text-align:left;white-space:nowrap">${esc(s.name)}</td>${cells}<td>${P}</td><td>${A}</td><td>${L}</td></tr>`}).join("")}
  </tbody></table></div></section>`}
J.act("attSet",async el=>{const [sid,f,dx]=el.dataset.x.split("|");const d=dx||ui().attDate||today();const m=d.slice(0,7),day=String(+d.slice(8));let v=el.value;if(f==="ot")v=v===""?"":+v||0;const s0=J.get("accounts",sid);const extra=[];
  if(f==="s"&&v==="W"&&s0&&!J.R.isWeekOff(s0,d)){
    if(J.R.inWait(s0,d)){if(!J.R.isAdmin()){toast("No weekly off until "+fmtDate(J.R.woFrom(s0,d))+" — only an Administrator can allow one in this period.");J.render();return}extra.push("weekly off allowed by admin within the waiting period")}
    else if(J.R.hasWO(s0)){const reg=J.R.scheduledOffIn(s0,d);const wk=J.R.weekKey(d);await J.store.put("accounts",{...s0,woSwap:{...(s0.woSwap||{}),[wk]:d}});
      const rr=dayStatus(sid,reg);if(reg&&reg!==d&&(!rr?.s||rr.auto||rr.s==="W")){const mm=reg.slice(0,7);await J.store.patch("attendance",mm,{days:{[String(+reg.slice(8))]:{[sid]:{s:"P",auto:1}}}})}extra.push("weekly off moved from "+DOW[J.parseISO(reg).getDay()]+" "+fmtDate(reg)+" to "+DOW[J.parseISO(d).getDay()]+" "+fmtDate(d))}}
  const prev=dayStatus(sid,d)||{};const patch={days:{[day]:{[sid]:{[f]:v,auto:null}}}};if(f==="in"&&!prev.s)patch.days[day][sid].s="P";if(await J.safe(()=>J.store.patch("attendance",m,patch))){const nm=J.get("accounts",sid)?.name||"";const lbl={s:"status",in:"in time",out:"out time",in2:"second in time",out2:"second out time",ot:"OT",st:"shift start"}[f]||f;
    if(String(prev[f]??"")!==String(v??""))await J.H.logChange(m,{type:"attendance",sid,date:d,text:nm+" · "+fmtDate(d)+" "+lbl+": "+(f==="s"?(ST[prev[f]]||"unmarked"):(prev[f]||"—"))+" → "+(f==="s"?(ST[v]||"unmarked"):(v||"—"))+(extra.length?" · "+extra.join("; "):"")}).catch(()=>{});if(m<=J.H.lastClosedMonth())J.H.syncSoon("attendance changed for "+nm+" on "+fmtDate(d))}});
J.act("allPresent",async()=>{const d=ui().attDate||today();const m=d.slice(0,7),day=String(+d.slice(8));const recs=att(m)[day]||{};const p={};for(const s of staff())if(!recs[s.id]?.s)p[s.id]={s:weekOff(s,d)?"W":"P"};if(!Object.keys(p).length)return toast("Everyone is already marked");await J.safe(()=>J.store.patch("attendance",m,{days:{[day]:p}}),"Marked "+Object.keys(p).length+" staff")});
J.act("attImport",()=>J.openImport("att"));

// one editable punch row (daily list uses the staff name as first cell, the employee month view uses the date)
function punchRow(s,date,r,first){const wo=weekOff(s,date);const late=lateMins(s,r);const wm=J.R.workMin(s,r);const auto=J.R.autoOT(s,r);const x=s.id+"|";const dx=first?"|"+date:"";const id=(k)=>k+"-"+s.id+(first?"-"+date:"");const svc=J.H.stints(s).length?J.H.inService(s,date):s.active!==false;const dis=svc?"":"disabled";const wait=svc&&J.R.hasWO(s)&&J.R.inWait(s,date);
  const ti=(f)=>`<input type="time" data-ach="attSet" data-x="${x}${f}${dx}" id="${id("a"+f)}" value="${esc(r[f]||"")}" style="width:auto" ${dis}>`;
  return `<tr style="${!svc?"opacity:.45":""}">${first||`<td style="text-align:left">${esc(s.name)}<div class="hint">${esc(s.desig||"")}${wo?" · week off day":""}${wait?" · no weekly off yet":""}</div></td>`}
    <td>${svc?`<select data-ach="attSet" data-x="${x}s${dx}" id="${id("as")}" aria-label="Status for ${esc(s.name)} ${date}"><option value="">—</option>${Object.entries(ST).map(([k,l])=>`<option value="${k}" ${r.s===k?"selected":""}>${l}</option>`).join("")}</select>`:'<span class="muted">Not employed</span>'}</td>
    <td>${ti("in")}</td><td>${ti("out")}</td><td>${ti("in2")}</td><td>${ti("out2")}</td>
    <td><input type="time" data-ach="attSet" data-x="${x}st${dx}" id="${id("ast")}" value="${esc(r.st||"")}" placeholder="${esc(J.R.segsFor(s,r)[0]?.[0]||"")}" style="width:auto" title="${r.sh?esc(J.R.rules().shifts[r.sh]?.label||r.sh)+" this day. ":""}Leave blank to use ${esc(J.R.segsFor(s,r)[0]?.[0]||"")}" ${dis}></td>
    <td>${wm?J.R.hm(wm):'<span class="muted">—</span>'}${J.R.secondOnly(s,r)&&r.s==="P"?'<div><span class="chip warn" title="Reported for the second spell only — paid as a half-day">½ day · 2nd spell</span></div>':J.R.secondOnly(s,r)&&(r.s==="WW"||r.s==="W")?'<div><span class="chip ok" title="Second spell on the weekly off — 1 day for the off + ½ day duty">1½ days · 2nd spell on off</span></div>':""}</td><td>${late?`<span class="chip ${J.R.lateFrac(late)?"warn":"plain"}" title="${esc(J.R.slabText(late))}">${late}m${J.R.lateFrac(late)?" · "+Math.round(J.R.lateFrac(late)*100)+"%":""}</span>`:'<span class="muted">—</span>'}</td>
    <td><input type="number" step="0.25" min="0" style="width:72px" data-ach="attSet" data-x="${x}ot${dx}" id="${id("aot")}" value="${esc(r.ot??"")}" placeholder="${auto?auto:"0"}" ${dis}></td>${first?`<td class="hint">${!svc?"":r.s?(r.auto?"auto":"by hand"):""}</td>`:""}</tr>`}
// ---------- Employee-wise monthly attendance ----------
function empMonth(s,m){const D=daysInMonth(m);const days=att(m);const t=today();const rows=[];const cnt={P:0,H:0,A:0,L:0,W:0,WW:0,O:0,un:0,late:0,lateMin:0,ot:0,out:0};
  for(let i=1;i<=D;i++){const date=m+"-"+pad(i);const r=days[String(i)]?.[s.id]||{};const svc=J.H.stints(s).length?J.H.inService(s,date):s.active!==false;const fut=date>t;
    const k=r.s||"";if(!svc)cnt.out++;else if(!fut){if(k)cnt[k]=(cnt[k]||0)+1;else if(weekOff(s,date))cnt.W++;else cnt.un++;const lm=lateMins(s,r);if(lm){cnt.late++;cnt.lateMin+=lm}cnt.ot+=+r.ot||0}
    rows.push({date,i,r,svc,fut,k,wo:weekOff(s,date),late:lateMins(s,r)})}return {rows,cnt}}
function vEmpAtt(){const U=ui();const all=J.staffInMonth(WM()).sort((a,b)=>(a.code||"").localeCompare(b.code||""));if(U.emp&&!all.some(x=>x.id===U.emp)){const keep=J.get("accounts",U.emp);if(keep&&U.empKeep===U.emp)all.push(keep)}if(!U.emp||!J.get("accounts",U.emp))U.emp=all.find(s=>s.active!==false)?.id||all[0]?.id;const s=J.get("accounts",U.emp);
  const m=WM();if(!s)return J.emptyRow?`<div class="panel pb muted">No staff yet.</div>`:"";
  const {rows,cnt}=empMonth(s,m);const c=calc(s,m,J.get("payroll",m)?.ov?.[s.id]||{});const sv=J.get("vouchers","salm-"+m);const T=s.terms?.auto?s.terms:null;
  const opt=(r)=>`<option value="">—</option>`+Object.entries(ST).map(([k,l])=>`<option value="${k}" ${r.s===k?"selected":""}>${l}</option>`).join("");
  const chip=(k,n,cls)=>n?`<span class="chip ${cls||"plain"}">${k} ${n}</span>`:"";
  return `<div class="filters">${fld("Employee",`<select id="ea-emp" data-ui="staff.emp">${all.map(x=>`<option value="${x.id}" ${x.id===s.id?"selected":""}>${esc((x.code?x.code+" · ":"")+x.name)}${x.active===false?" (former)":""}</option>`).join("")}</select>`)}
    ${fld("Month",`<input type="month" id="ea-month" data-ui="staff.wm" value="${m}">`)}<div class="row"><button class="btn small" data-a="eaMonth" data-x="-1" aria-label="Previous month">‹ Prev</button><button class="btn small" data-a="eaMonth" data-x="1" aria-label="Next month">Next ›</button></div>
    <div class="row" style="margin-left:auto;flex-wrap:wrap"><button class="btn w" data-a="eaFill" data-x="${s.id}">Mark unmarked days present</button><button class="btn" data-a="eaPrint" data-x="${s.id}">Print / PDF</button><button class="btn" data-a="staffProfile" data-x="${s.id}">Profile</button></div></div>
  <div class="kpis">${J.kpi("Paid days",String(c.paid),c.svc+" days in service"+(cnt.out?" · "+cnt.out+" not employed":""))}${J.kpi("Salary earned",money0(c.earned),money0(J.H.salaryOn(s,J.monthEnd(m)<today()?J.monthEnd(m):today())||0)+"/month"+(c.exempt?" · fixed":""))}${J.kpi("Late · OT",c.late+" late · "+c.ot+" h OT",c.lateMin?c.lateMin+" min late":"")}${J.kpi("Net pay",money0(c.net),sv?"Posted in "+sv.no:"Not posted yet")}</div>
  <div class="row" style="gap:6px;flex-wrap:wrap;margin:-4px 0 10px">${chip("Present",cnt.P,"ok")}${chip("Half-day",cnt.H,"warn")}${chip("Absent",cnt.A,"bad")}${chip("Paid leave",cnt.L)}${chip("Week off",cnt.W)}${chip("Worked on week off",cnt.WW,"ok")}${chip("Not scheduled",cnt.O)}${chip("Unmarked",cnt.un,"warn")}${T?`<span class="hint">Service terms: ${T.fixed?"fixed salary · ":""}attends ${T.days.length===7?"daily":T.days.map(i=>DOW[i]).join(", ")} · marked automatically</span>`:""}</div>
  <div class="panel"><div class="tbl-wrap"><table class="att"><thead><tr><th style="text-align:left">Date</th><th>Status</th><th>In</th><th>Out</th><th>In (2)</th><th>Out (2)</th><th>Shift start</th><th>Worked</th><th>Late</th><th>OT hrs</th><th>Marked</th></tr></thead><tbody>
  ${rows.map(({date,r,fut,wo})=>punchRow(s,date,r,`<td style="text-align:left;white-space:nowrap${fut?";opacity:.7":""}">${fmtDate(date)} <span class="hint">${DOW[J.parseISO(date).getDay()]}${wo?" · off":""}</span></td>`)).join("")}
  </tbody></table></div></div><p class="hint">Changes save as you make them. For a month already posted, the salary entry is rewritten and the change is logged on the Payroll tab. "Auto" days were filled from the person's tenure or service terms; days you change become "by hand" and are never overwritten.</p>`}
J.act("attDay",el=>{const U=ui();if(!el.value)return;U.attDate=el.value;U.wm=el.value.slice(0,7);J.render()});
J.act("eaMonth",el=>{const U=ui();const [y,mm]=WM().split("-").map(Number);const d=new Date(y,mm-1+ +el.dataset.x,1);U.wm=J.iso(d).slice(0,7);J.render()});
J.act("empAtt",el=>{J.closeDrawer();const U=ui();U.emp=el.dataset.x;J.go("staff","empatt")});
J.act("eaFill",async el=>{const sid=el.dataset.x,m=WM();const s=J.get("accounts",sid);const {rows}=empMonth(s,m);const p={};let n=0;for(const x of rows)if(x.svc&&!x.fut&&!x.r.s){const k=s.terms?.auto&&!(s.terms.days||[]).includes(J.parseISO(x.date).getDay())?"O":x.wo?"W":"P";(p[String(x.i)]??={})[sid]={s:k,auto:1};n++}
  if(!n)return toast("Every day is already marked");if(await J.safe(()=>J.store.patch("attendance",m,{days:p}),n+" days marked")){await J.H.logChange(m,{type:"attendance",sid,text:s.name+" · "+n+" unmarked days marked present / week off"}).catch(()=>{});if(m<=J.H.lastClosedMonth())J.H.syncSoon("attendance filled for "+s.name)}});
J.act("eaPrint",el=>{const s=J.get("accounts",el.dataset.x),m=WM();const {rows,cnt}=empMonth(s,m);const c=calc(s,m,J.get("payroll",m)?.ov?.[s.id]||{});
  J.printDoc("Attendance "+s.name+" "+monthLabel(m),`<div class="hd"><div><h1>${esc(J.settings().business||"JCGG")}</h1><div class="sub">Attendance card — <b>${esc(s.name)}</b>${s.code?" · "+esc(s.code):""}${s.desig?" · "+esc(s.desig):""}</div></div><div class="sub">${monthLabel(m)}</div></div>
  <table><thead><tr><th>Date</th><th>Day</th><th>Status</th><th>In</th><th>Out</th><th>In (2)</th><th>Out (2)</th><th class="num">Worked</th><th class="num">Late (min)</th><th class="num">OT (h)</th><th>Sign</th></tr></thead><tbody>${rows.map(x=>{const wm=J.R.workMin(s,x.r),oh=x.svc?J.R.otHours(s,x.r):0;return `<tr><td>${fmtDate(x.date)}</td><td>${DOW[J.parseISO(x.date).getDay()]}</td><td>${!x.svc?"Not employed":x.fut?"":ST[x.r.s]||(x.wo?"Week off":"Unmarked")}</td><td>${esc(x.r.in||"")}</td><td>${esc(x.r.out||"")}</td><td>${esc(x.r.in2||"")}</td><td>${esc(x.r.out2||"")}</td><td class="num">${wm?J.R.hm(wm):""}</td><td class="num">${x.late?x.late+(J.R.lateFrac(x.late)?" ("+Math.round(J.R.lateFrac(x.late)*100)+"%)":""):""}</td><td class="num">${oh||""}</td><td style="width:60px"></td></tr>`}).join("")}</tbody></table>
  <table style="max-width:560px"><tbody><tr><th>Present</th><td class="num">${cnt.P}</td><th>Half-day</th><td class="num">${cnt.H}</td><th>Absent</th><td class="num">${cnt.A}</td></tr><tr><th>Paid leave</th><td class="num">${cnt.L}</td><th>Week off</th><td class="num">${cnt.W}</td><th>Not scheduled</th><td class="num">${cnt.O}</td></tr><tr><th>Paid days</th><td class="num"><b>${c.paid}</b></td><th>Late marks</th><td class="num">${c.late}</td><th>OT hours</th><td class="num">${c.ot}</td></tr><tr><th>OT earned</th><td class="num">${inr.format(c.otPay)} (${c.ot} h)</td><th>Short duty</th><td class="num">${inr.format(c.shortDed)} (${c.shortH} h)</td><th>Late</th><td class="num">${inr.format(c.lateDed)}</td></tr><tr><th>Final OT paid</th><td class="num"><b>${inr.format(c.finalOT)}</b></td><th>Balance cut from salary</th><td class="num">${inr.format(c.fromSal)}</td><th></th><td></td></tr><tr><th>Salary earned</th><td class="num">${inr.format(c.earned)}</td><th>Gross</th><td class="num">${inr.format(c.grossPay)}</td><th>Net pay</th><td class="num"><b>${inr.format(c.net)}</b></td></tr></tbody></table>
  <div class="sig"><div>Employee</div><div>Supervisor</div><div>Approved by</div></div>`)});

// ---------- Payroll ----------
function calc(s,m,ov={}){const D=daysInMonth(m),HH=J.H,hist=HH.stints(s).length>0;const basis=s.sal?.basis==="30_days"?30:D;const exempt=!!(s.sal?.exempt||s.salaryCutExempt||s.terms?.fixed);
  const gNow=hist?HH.salaryOn(s,J.monthEnd(m)<today()?J.monthEnd(m):today()):(+s.sal?.gross||0);const gross=gNow,perDay=gNow/basis;const days=att(m);const last=m===today().slice(0,7)?+today().slice(8):D;const unmarkedPresent=J.settings().unmarkedPresent!==false;
  let paid=0,P=0,H_=0,A=0,L=0,W=0,WW=0,un=0,late=0,lateMin=0,ot=0,svc=0,accrue=0,lateAuto=0,otAuto=0,shortH=0,shortAuto=0;const RR=J.R.rules(),grace=(RR.slabs.find(x=>!+x[2])||[0,0])[1],otMul=+J.settings().otRate||1;
  for(let i=1;i<=D;i++){const date=m+"-"+pad(i);if(i>last)continue;if(hist?!HH.inService(s,date):(s.doj&&date<s.doj))continue;svc++;const sal=hist?HH.salaryOn(s,date):gross;const r=days[String(i)]?.[s.id];let k=r?.s;if(!k){if(weekOff(s,date))k="W";else{un++;k=unmarkedPresent?"P":"A"}}
    if(k==="O"){k="W"}if(k==="W"&&r?.in&&!exempt)k="WW";const half2=!!(r&&!exempt&&J.R.secondOnly(s,r));if(k==="P"&&half2)k="H";let w=k==="P"||k==="L"||k==="W"?1:k==="H"?0.5:k==="WW"?(half2?1.5:2):0;if(k==="P")P++;else if(k==="H")H_++;else if(k==="A")A++;else if(k==="L")L++;else if(k==="W")W++;else if(k==="WW")WW++;if(exempt)w=1;
    paid+=w;accrue+=sal/D-(1-w)*sal/basis;if(!exempt&&r&&(k==="P"||k==="H"||k==="WW")){const lm=lateMins(s,r);if(lm>grace){late++;lateMin+=lm;lateAuto+=J.R.lateFrac(lm)*sal/basis}const oh=J.R.otHours(s,r);const hr=(sal/basis)/(+RR.otAfter||10);if(oh>0){ot+=oh;otAuto+=oh*hr*otMul}
      if((k==="P"||(k==="WW"&&!half2))&&(r.ot===""||r.ot==null)&&r.in&&(r.out2||r.out)){const wm=J.R.workMin(s,r);const sh=Math.max(0,(+RR.otAfter||10)*60-wm)/60;if(sh>0){shortH+=sh;shortAuto+=sh*hr}}}}
  const H=H_;const earned=r2(Math.max(0,accrue)),otPay=r2(otAuto),bonus=+ov.bonus||0,penalty=+ov.penalty||0;const lateDed=ov.late!=null&&ov.late!==""?+ov.late:r2(lateAuto+late*(+J.settings().lateDed||0));const shortDed=ov.short!=null&&ov.short!==""?+ov.short:r2(shortAuto);shortH=Math.round(shortH*100)/100;const setOff=RR.lateFirstOT?r2(Math.min(otPay,shortDed+lateDed)):0;const finalOT=r2(otPay-setOff),fromSal=r2(shortDed+lateDed-setOff);const lateOT=setOff,lateSal=fromSal;ot=Math.round(ot*100)/100;const adj=+ov.adj||0,adjP=adj>0?adj:0,adjM=adj<0?-adj:0;const grossPay=r2(earned+finalOT+bonus+adjP);const grossEarned=r2(grossPay-penalty-fromSal-adjM);
  const basicE=r2((+s.sal?.basic||gross)*Math.min(paid,D)/D);const pf=s.sal?.pf?r2(Math.min(basicE,15000)*0.12):0;const esic=s.sal?.esic&&gross<=21000?Math.ceil(grossEarned*0.0075):0;const pt=s.sal?.pt!==false?PT_WB(grossEarned):0;const tds=ov.tds!=null&&ov.tds!==""?+ov.tds:(+s.sal?.tds||0);
  // advance and loan balances as at month end, leaving out this month's own salary recovery
  const sv=J.get("vouchers","salm-"+m);const balEx=id=>{let b=J.balanceOf(id,J.monthEnd(m));if(sv)for(const l of sv.lines)if(l.a===id)b-=l.dr-l.cr;return Math.max(0,r2(b))};
  const advBal=balEx("adv-"+s.id),loanBal=balEx("loan-"+s.id);const stat=r2(pf+esic+pt+tds);let room=Math.max(0,grossEarned-stat);
  const adv=r2(ov.adv!=null&&ov.adv!==""?Math.min(+ov.adv,advBal):Math.min(advBal,s.sal?.instal!==""&&s.sal?.instal!=null?+s.sal.instal:advBal,room));room=Math.max(0,room-adv);
  const loan=r2(ov.loan!=null&&ov.loan!==""?Math.min(+ov.loan,loanBal):Math.min(loanBal,+s.sal?.loanEmi||0,room));const food=r2(ov.food!=null&&ov.food!==""?+ov.food:(J.settings().staffFoodRecover!==false&&J.staffFood?J.staffFood(s.id,m):0));
  return {D,svc,basis,exempt,perDay:r2(perDay),paid,P,H,A,L,W,WW,un,late,lateMin,lateDed,lateOT,lateSal,shortH,shortDed,setOff,finalOT,fromSal,ot,earned,otPay,bonus,penalty,adj,adjNote:ov.adjNote||"",grossPay,grossEarned,pf,esic,pt,tds,stat,advBal,adv,loanBal,loan,food,ded:r2(penalty+fromSal+adjM+stat+adv+loan+food),net:r2(grossEarned-stat-adv-loan-food)}}
J.payCalc=calc;
const inSvc=(s,m)=>J.H.stints(s).length?J.H.inServiceRange(s,m+"-01",J.monthEnd(m)):s.active!==false;
const svOf=m=>J.get("vouchers","salm-"+m);const onV=(v,sid)=>!!v&&v.lines.some(l=>l.a===sid);
const paidV=(m,sid)=>{const run=J.get("payroll",m)||{};const v=run.paid?.[sid]&&J.get("vouchers",run.paid[sid]);if(v)return v;const pre=J.get("vouchers","salpre-"+m);return onV(pre,sid)?pre:null};
function payRows(m){const run=J.get("payroll",m)||{};const v=svOf(m);return staff(true).filter(s=>inSvc(s,m)||onV(v,s.id)).map(s=>({s,c:calc(s,m,run.ov?.[s.id]||{}),posted:onV(v,s.id),pv:paidV(m,s.id)})).filter(r=>r.c.svc||r.posted)}
function vPayroll(){const U=ui();const m=WM();const run=J.get("payroll",m)||{};const ov=run.ov||{};const sv=svOf(m);
  const rows=payRows(m);const T=k=>r2(rows.reduce((a,r)=>a+(+r.c[k]||0),0));const unpaid=rows.filter(r=>r.posted&&!r.pv&&r.c.net>0);const closed=m<=J.H.lastClosedMonth();const fy=J.fyOf(J.monthEnd(m));
  const inp=(sid,k,val,ph,w=74)=>`<input class="w" style="width:${w}px" type="number" step="any" data-ach="payOv" data-x="${sid}|${k}" id="p${k}-${sid}" value="${esc(val??"")}" ${ph!=null?`placeholder="${esc(ph)}"`:""}>`;
  return `<div class="filters">${fld("Salary month",`<input type="month" id="pr-m" data-ui="staff.wm" value="${m}">`)}<span class="hint">${sv?`Ledger entry <b>${esc(sv.no)}</b> dated ${fmtDate(sv.date)}`:closed?"Not posted yet":"Posts automatically after "+fmtDate(J.monthEnd(m))}. Unmarked days count as ${J.settings().unmarkedPresent!==false?"present":"absent"}.</span>
    <div class="row" style="margin-left:auto;flex-wrap:wrap"><button class="btn w" data-a="postPayroll" ${closed?"":"disabled"}>Re-check ${monthLabel(m)}</button><button class="btn primary w" data-a="settle" data-x="">Monthly settlement</button><button class="btn" data-a="printRegister">Print salary sheet</button><button class="btn" data-a="printFY">Print ${esc(fy.label)} register</button><button class="btn primary w" data-a="paySalaries" ${unpaid.length?"":"disabled"}>Pay salaries (${unpaid.length})</button><button class="btn" data-a="neft">NEFT sheet</button></div></div>
  <div class="kpis">${J.kpi("Gross pay",money0(T("grossPay")),rows.length+" staff · OT "+money0(T("otPay"))+" · perks "+money0(T("bonus")))}${J.kpi("OT · short duty · late",money0(T("finalOT"))+" final OT","OT "+money0(T("otPay"))+" − short "+money0(T("shortDed"))+" − late "+money0(T("lateDed"))+(T("fromSal")?" · "+money0(T("fromSal"))+" from salary":"")+" · penalty "+money0(T("penalty")))}${J.kpi("Statutory · advances · loans",money0(T("stat")+T("adv")+T("loan")),"PT "+money0(T("pt"))+" · adv "+money0(T("adv"))+" · loan "+money0(T("loan")))}${J.kpi("Net pay",money0(T("net")),rows.filter(r=>r.pv).length+" paid")}</div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Staff</th><th class="num">Paid days</th><th class="num">Salary earned</th><th class="num">Final OT</th><th class="num">Perks / bonus</th><th class="num">Late marks · ded.</th><th class="num">Penalty</th><th class="num">PT / PF / ESIC / TDS</th><th class="num">Advance rec.</th><th class="num">Loan EMI</th><th class="num">Net pay</th><th>Status</th><th></th></tr></thead><tbody>
  ${rows.length?rows.map(({s,c,posted,pv})=>`<tr><td>${esc(s.name)}<div class="hint">${esc(s.code||"")} · ${money0(J.H.salaryOn(s,J.monthEnd(m))||s.sal?.gross||0)}/mo · ₹${inr.format(c.perDay)}/day${c.un?` · <span style="color:var(--warn)">${c.un} unmarked</span>`:""}</div></td><td class="num">${c.paid}<div class="hint">P${c.P} H${c.H} L${c.L} W${c.W}${c.WW?" 2×"+c.WW:""} A${c.A}</div></td><td class="num">${inr.format(c.earned)}</td><td class="num">${c.ot||c.shortH||c.lateDed?`<span title="OT ${c.ot} h = ₹${inr.format(c.otPay)}; short duty ${c.shortH} h = ₹${inr.format(c.shortDed)}; late ₹${inr.format(c.lateDed)}">${inr.format(c.finalOT)}</span><div class="hint">+${c.ot}h − ${c.shortH}h short${c.lateDed?" − late":""}</div>${c.fromSal?`<div class="hint" style="color:var(--bad)">−${inr.format(c.fromSal)} from salary</div>`:""}`:"—"}</td>
    <td class="num">${inp(s.id,"bonus",ov[s.id]?.bonus)}</td><td class="num">${c.late?c.late+"× · ":""}${inp(s.id,"late",ov[s.id]?.late,J.inr0.format(c.lateDed),64)}</td><td class="num">${inp(s.id,"penalty",ov[s.id]?.penalty)}</td>
    <td class="num">${[c.pt,c.pf,c.esic,c.tds].map(x=>x?J.inr0.format(x):"–").join(" / ")}</td><td class="num">${c.advBal>0||ov[s.id]?.adv?inp(s.id,"adv",ov[s.id]?.adv,J.inr0.format(c.adv))+`<div class="hint">bal ${money0(c.advBal)}</div>`:"—"}</td><td class="num">${c.loanBal>0||ov[s.id]?.loan?inp(s.id,"loan",ov[s.id]?.loan,J.inr0.format(c.loan))+`<div class="hint">bal ${money0(c.loanBal)}</div>`:"—"}</td><td class="num"><b>${inr.format(c.net)}</b></td>
    <td>${pv?`<span class="chip ok">Paid · ${esc(pv.no)}</span>`:posted?`<span class="chip warn">Posted · ${esc(sv.no)}</span>`:closed?'<span class="chip plain">Not posted</span>':'<span class="chip plain">Posts at month end</span>'}</td><td style="white-space:nowrap"><button class="btn small w" data-a="settle" data-x="${s.id}">Settle</button> <button class="btn small" data-a="payslip" data-x="${s.id}">Payslip</button></td></tr>`).join(""):J.emptyRow(13,"Nobody was in service this month","Joinings, exits and salaries come from each person's employment history.")}
  </tbody>${rows.length?`<tfoot><tr><td>Total</td><td></td><td class="num">${inr.format(T("earned"))}</td><td class="num">${inr.format(T("finalOT"))}</td><td class="num">${inr.format(T("bonus"))}</td><td class="num">${inr.format(T("lateDed"))}</td><td class="num">${inr.format(T("penalty"))}</td><td class="num">${inr.format(T("stat"))}</td><td class="num">${inr.format(T("adv"))}</td><td class="num">${inr.format(T("loan"))}</td><td class="num">${inr.format(T("net"))}</td><td colspan="2"></td></tr></tfoot>`:""}</table></div></div>
  ${sv?`<section class="panel"><h2>Ledger entry ${esc(sv.no)} · ${fmtDate(sv.date)}</h2><div class="tbl-wrap">${entryTable(sv)}</div></section>`:""}
  ${(()=>{const lg=(run.log||[]).slice().reverse();return `<section class="panel"><h2>Change log · ${monthLabel(m)} · ${lg.length}</h2><div class="tbl-wrap" style="max-height:320px"><table><tbody>${lg.map(e=>`<tr><td style="white-space:nowrap">${new Date(e.at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}</td><td><span class="chip ${e.type==="updated"||e.type==="adjustment"?"warn":"plain"}">${esc(e.type)}</span></td><td>${esc(e.text)}</td><td class="muted">${esc(e.by||"")}</td></tr>`).join("")||'<tr><td class="muted">No changes recorded for this month.</td></tr>'}</tbody></table></div></section>`})()}
  <p class="hint">Each month's salaries go to the ledger as one entry dated the last day of the month, with every person's breakup on its own lines: salary for paid days, overtime and perks are debited to their expense heads; late and penalty deductions, PT/PF/ESIC/TDS, advance recovery (to the person's Advance ledger) and loan EMI (to their Loan ledger) are credited; the net pay is credited to the person's salary ledger. If attendance, perks, deductions, an exit, a rejoining or a salary revision for a past month changes, that month's entry is rewritten in place (same voucher number) and the change is recorded in the log above. Months before the book start (${monthLabel(J.settings().startMonth)}) are marked as paid against "Salaries settled before book start".</p>`}
function entryTable(v){const by={};for(const l of v.lines){const k=l.a;(by[k]??={a:k,dr:0,cr:0,n:0});by[k].dr+=l.dr;by[k].cr+=l.cr;by[k].n++}
  const rows=Object.values(by).map(x=>{const net=r2(x.dr-x.cr);return {...x,net,acc:J.get("accounts",x.a)}}).sort((a,b)=>(b.net>0)-(a.net>0)||((a.acc?.kind==="staff")-(b.acc?.kind==="staff"))||(a.acc?.name||"").localeCompare(b.acc?.name||""));
  return `<table><thead><tr><th>Ledger</th><th class="num">Debit ₹</th><th class="num">Credit ₹</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.acc?.name||x.a)}${x.n>1?` <span class="muted">(${x.n} lines)</span>`:""}</td><td class="num">${x.net>0?inr.format(x.net):""}</td><td class="num">${x.net<0?inr.format(-x.net):""}</td></tr>`).join("")}</tbody><tfoot><tr><td>Total</td><td class="num">${inr.format(r2(rows.reduce((t,x)=>t+Math.max(0,x.net),0)))}</td><td class="num">${inr.format(r2(rows.reduce((t,x)=>t+Math.max(0,-x.net),0)))}</td></tr></tfoot></table>`}
J.salaryEntryTable=entryTable;
const bizHead=(t,sub)=>`<div class="hd"><div><h1>${esc(J.settings().business||"JCGG")}</h1><div class="sub">${t}</div></div><div class="sub" style="text-align:right">${sub||""}</div></div>`;
J.act("printRegister",()=>{const m=WM();const rows=payRows(m);const sv=svOf(m);const f=n=>n?inr.format(n):"–";const T=k=>r2(rows.reduce((a,r)=>a+(+r.c[k]||0),0));
  J.printDoc("Salary sheet "+monthLabel(m),bizHead("Salary sheet — <b>"+monthLabel(m)+"</b>",sv?"Ledger entry "+esc(sv.no)+" · "+fmtDate(sv.date):"Not yet posted")+
  `<table><thead><tr><th>#</th><th>Code</th><th>Name · designation</th><th class="num">Rate / month</th><th class="num">Days in service</th><th>Attendance</th><th class="num">Paid days</th><th class="num">Salary earned</th><th class="num">OT hrs (+ / − short)</th><th class="num">Final OT</th><th class="num">Perks</th><th class="num">Gross</th><th class="num">Short + late from salary</th><th class="num">Penalty</th><th class="num">PT/PF/ ESIC/TDS</th><th class="num">Advance rec.</th><th class="num">Loan EMI</th><th class="num">Net pay</th><th>Paid</th><th style="width:70px">Signature</th></tr></thead><tbody>
  ${rows.map(({s,c,pv},i)=>`<tr><td>${i+1}</td><td>${esc(s.code||"")}</td><td>${esc(s.name)}<div class="muted">${esc(J.H.stints(s).filter(x=>x.join<=J.monthEnd(m)).at(-1)?.desig||s.desig||"")}</div></td><td class="num">${inr.format(J.H.salaryOn(s,J.monthEnd(m))||0)}</td><td class="num">${c.svc}</td><td>P${c.P} H${c.H} L${c.L} W${c.W}${c.WW?" WW"+c.WW:""} A${c.A}</td><td class="num">${c.paid}</td><td class="num">${f(c.earned)}</td><td class="num">${c.ot||c.shortH?"+"+c.ot+" / −"+c.shortH:"–"}</td><td class="num">${f(c.finalOT)}</td><td class="num">${f(c.bonus)}</td><td class="num">${f(c.grossPay)}</td><td class="num">${f(c.fromSal)}</td><td class="num">${f(c.penalty)}</td><td class="num">${f(c.stat)}</td><td class="num">${f(c.adv)}</td><td class="num">${f(c.loan)}</td><td class="num"><b>${inr.format(c.net)}</b></td><td>${pv?esc(pv.no)+"<br>"+fmtDate(pv.date):""}</td><td></td></tr>`).join("")}</tbody>
  <tfoot><tr><td colspan="7">Total · ${rows.length} staff</td><td class="num">${f(T("earned"))}</td><td class="num">${f(r2(rows.reduce((a,r)=>a+r.c.ot-r.c.shortH,0)))+" h"}</td><td class="num">${f(T("finalOT"))}</td><td class="num">${f(T("bonus"))}</td><td class="num">${f(T("grossPay"))}</td><td class="num">${f(T("fromSal"))}</td><td class="num">${f(T("penalty"))}</td><td class="num">${f(T("stat"))}</td><td class="num">${f(T("adv"))}</td><td class="num">${f(T("loan"))}</td><td class="num">${inr.format(T("net"))}</td><td colspan="2"></td></tr></tfoot></table>
  ${sv?`<h2>Accounting entry ${esc(sv.no)}</h2><div style="max-width:520px">${entryTable(sv)}</div>`:""}
  ${(J.get("payroll",m)?.log||[]).length?`<h2>Changes made after posting</h2><table><tbody>${J.get("payroll",m).log.map(e=>`<tr><td class="num">${new Date(e.at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}</td><td>${esc(e.type)}</td><td>${esc(e.text)}</td><td>${esc(e.by||"")}</td></tr>`).join("")}</tbody></table>`:""}
  <div class="sig"><div>Prepared by</div><div>Checked by</div><div>Approved by</div></div>`,true)});
J.act("printFY",()=>{const m0=WM();const fy=J.fyOf(J.monthEnd(m0));const y=fy.y;const months=J.monthsBetween(y+"-04",(y+1)+"-03").filter(m=>m<=J.H.lastClosedMonth());
  const data={};const tot={};for(const m of months)for(const r of payRows(m)){const d=(data[r.s.id]??={s:r.s,m:{},g:0,ded:0,adv:0,loan:0,net:0});d.m[m]=r.c.grossPay;d.g+=r.c.grossPay;d.ded+=r.c.penalty+r.c.fromSal+r.c.stat;d.adv+=r.c.adv;d.loan+=r.c.loan;d.net+=r.c.net;tot[m]=(tot[m]||0)+r.c.grossPay}
  const list=Object.values(data).sort((a,b)=>(a.s.code||"").localeCompare(b.s.code||""));const f=n=>n?J.inr0.format(n):"–";const ML=m=>monthLabel(m).replace(/ \d+$/,"");
  J.printDoc("Salary register "+fy.label,bizHead("Salary register — <b>"+esc(fy.label)+"</b> · gross pay by month",months.length?monthLabel(months[0])+" to "+monthLabel(months.at(-1)):"")+
  `<table><thead><tr><th>Code</th><th>Name</th>${months.map(m=>`<th class="num">${ML(m)}</th>`).join("")}<th class="num">Gross</th><th class="num">Late, penalty, statutory</th><th class="num">Advance rec.</th><th class="num">Loan EMI</th><th class="num">Net pay</th></tr></thead><tbody>
  ${list.map(d=>`<tr><td>${esc(d.s.code||"")}</td><td>${esc(d.s.name)}</td>${months.map(m=>`<td class="num">${f(d.m[m])}</td>`).join("")}<td class="num">${f(d.g)}</td><td class="num">${f(d.ded)}</td><td class="num">${f(d.adv)}</td><td class="num">${f(d.loan)}</td><td class="num"><b>${f(d.net)}</b></td></tr>`).join("")}</tbody>
  <tfoot><tr><td colspan="2">Total</td>${months.map(m=>`<td class="num">${f(tot[m])}</td>`).join("")}<td class="num">${f(list.reduce((t,d)=>t+d.g,0))}</td><td class="num">${f(list.reduce((t,d)=>t+d.ded,0))}</td><td class="num">${f(list.reduce((t,d)=>t+d.adv,0))}</td><td class="num">${f(list.reduce((t,d)=>t+d.loan,0))}</td><td class="num">${f(list.reduce((t,d)=>t+d.net,0))}</td></tr></tfoot></table>
  <h2>Monthly salary entries</h2><table><thead><tr><th>Month</th><th>Voucher</th><th>Date</th><th class="num">Amount ₹</th></tr></thead><tbody>${months.map(m=>{const v=svOf(m);return v?`<tr><td>${monthLabel(m)}</td><td>${esc(v.no)}</td><td>${fmtDate(v.date)}</td><td class="num">${inr.format(J.vAmount(v))}</td></tr>`:""}).join("")}</tbody></table>
  <div class="sig"><div>Prepared by</div><div>Checked by</div><div>Approved by</div></div>`,true)});
J.act("payOv",async el=>{const [sid,k]=el.dataset.x.split("|");const m=WM();const prev=J.get("payroll",m)?.ov?.[sid]?.[k];if(await J.safe(()=>J.store.patch("payroll",m,{ov:{[sid]:{[k]:el.value===""?"":+el.value}}}))){const nm=J.get("accounts",sid)?.name||"";await J.H.logChange(m,{type:"override",sid,text:nm+" · "+k+": "+(prev===undefined||prev===""?"—":prev)+" → "+(el.value||"—")}).catch(()=>{});if(m<=J.H.lastClosedMonth())J.H.syncSoon(k+" changed for "+nm)}});
J.act("postPayroll",async()=>{const m=WM();if(m>J.H.lastClosedMonth())return toast("Salaries for "+monthLabel(m)+" post automatically once the month ends.");const r=await J.safe(()=>J.H.syncMonth(m,"re-checked from payroll screen"));if(r&&r.main!==undefined)toast(r.main?"Salary entry posted":r.adj?"Salary entry updated":"Ledger already matches");J.render()});
// ---------- Monthly settlement (one person or everyone) ----------
const SK=[["bonus","Perks / bonus"],["penalty","Penalty"],["late","Late ded."],["short","Short duty"],["adj","Other ±"],["adv","Advance rec."],["loan","Loan EMI"],["food","Staff food"]];
function setlCalc(m,id,draft){const s=J.get("accounts",id);const base=J.get("payroll",m)?.ov?.[id]||{};const ov={...base,...(draft[id]||{})};for(const k in ov)if(ov[k]===null)delete ov[k];const c=calc(s,m,ov);const pv=paidV(m,id);const paidAmt=r2(J.all("vouchers").filter(v=>v.type==="payment"&&v.src?.col==="payroll"&&v.src?.id===m).reduce((t,v)=>t+v.lines.filter(l=>l.a===id).reduce((a,l)=>a+l.dr-l.cr,0),0));return {s,c,ov,base,pv,paidAmt,bal:r2(c.net-paidAmt)}}
function setlTable(m,ids,draft){const rows=ids.map(id=>setlCalc(m,id,draft));const tot=k=>r2(rows.reduce((t,r)=>t+(+(k in r?r[k]:r.c[k])||0),0));const f=n=>inr.format(n||0);
  const inp=(id,k,val,ph,w=78)=>`<input type="number" step="any" name="s-${id}-${k}" id="s-${id}-${k}" data-setl="${id}|${k}" value="${esc(val??"")}" placeholder="${esc(ph??"")}" style="width:${w}px">`;
  return `<div class="tbl-wrap"><table class="setl"><thead><tr><th>Employee</th><th class="num">Paid days</th><th class="num">Salary earned</th><th class="num">OT earned</th>${SK.map(([k,l])=>`<th class="num">${l}</th>`).join("")}<th>Note</th><th class="num">Final OT</th><th class="num">Gross</th><th class="num">Deductions</th><th class="num">Net payable</th><th class="num">Paid</th><th class="num">Balance</th></tr></thead><tbody>
  ${rows.map(({s,c,ov,paidAmt,bal})=>{const id=s.id;const auto={late:c.lateDed,short:c.shortDed,adv:c.adv,loan:c.loan,food:c.food};return `<tr><td style="white-space:nowrap"><b>${esc(s.name)}</b><div class="hint">${esc(s.code||"")} · ${money0(J.H.salaryOn(s,J.monthEnd(m))||0)}/mo${c.late?` · ${c.late} late`:""}${c.shortH?` · ${c.shortH} h short`:""}</div></td><td class="num">${c.paid}</td><td class="num">${f(c.earned)}</td><td class="num">${f(c.otPay)}<div class="hint">${c.ot} h</div></td>
    ${SK.map(([k])=>`<td class="num">${inp(id,k,ov[k],k in auto?J.inr0.format(auto[k]):"0")}${k==="adv"&&c.advBal?`<div class="hint">bal ${money0(c.advBal)}</div>`:k==="loan"&&c.loanBal?`<div class="hint">bal ${money0(c.loanBal)}</div>`:""}</td>`).join("")}
    <td><input name="s-${id}-adjNote" id="s-${id}-adjNote" data-setl="${id}|adjNote" value="${esc(ov.adjNote||"")}" placeholder="reason" style="width:120px"></td>
    <td class="num" id="sc-${id}-finalOT">${f(c.finalOT)}</td><td class="num" id="sc-${id}-gross">${f(c.grossPay)}</td><td class="num" id="sc-${id}-ded">${f(c.ded)}</td><td class="num"><b id="sc-${id}-net">${f(c.net)}</b></td><td class="num">${paidAmt?f(paidAmt):"—"}</td><td class="num"><b id="sc-${id}-bal" style="color:${bal<0?"var(--bad)":"inherit"}">${f(bal)}</b></td></tr>`}).join("")}</tbody>
  ${rows.length>1?`<tfoot><tr><td>Total · ${rows.length} staff</td><td></td><td class="num">${f(tot("earned"))}</td><td class="num">${f(tot("otPay"))}</td>${SK.map(()=>"<td></td>").join("")}<td></td><td class="num" id="st-finalOT">${f(tot("finalOT"))}</td><td class="num" id="st-gross">${f(tot("grossPay"))}</td><td class="num" id="st-ded">${f(tot("ded"))}</td><td class="num"><b id="st-net">${f(tot("net"))}</b></td><td class="num">${f(tot("paidAmt"))}</td><td class="num"><b id="st-bal">${f(tot("bal"))}</b></td></tr></tfoot>`:""}</table></div>`}
J.act("settle",el=>{const m=WM();const one=el.dataset.x;const ids=one?[one]:payRows(m).map(r=>r.s.id);if(!ids.length)return toast("Nobody was in service in "+monthLabel(m));const draft={};const closed=m<=J.H.lastClosedMonth();J.closeDrawer();
  const f=J.drawer({title:(one?J.get("accounts",one).name+" — ":"")+"Settlement · "+monthLabel(m),wide:true,submit:"Save settlement",body:`<p class="hint" style="margin:0">Blank boxes use the automatic figure shown in grey. Type an amount to override it; clear it to go back to automatic. Every change is recorded in the month's change log${closed?" and the salary entry is rewritten":""}.</p>
    <div id="setlBox">${setlTable(m,ids,draft)}</div>
    <div class="row" style="gap:14px;flex-wrap:wrap;align-items:flex-end"><label class="row" style="gap:6px"><input type="checkbox" name="payNow" id="f-payNow"> Pay the balance now</label>${fld("Pay date",dateI("payDate",m===today().slice(0,7)?today():m<today().slice(0,7)?today():J.monthEnd(m)))}${fld("Paid from",J.selA("payFrom",J.MONEY,J.accsOf(["bank"])[0]?.id||J.accsOf(["cash"])[0]?.id))}</div>`,
    onSubmit:async fd=>{const changes=[];const patch={};for(const id of ids){const base=J.get("payroll",m)?.ov?.[id]||{};const nm=J.get("accounts",id).name;for(const k of [...SK.map(x=>x[0]),"adjNote"]){const raw=fd["s-"+id+"-"+k];if(raw===undefined)continue;const v=k==="adjNote"?String(raw).trim():(raw===""?"":+raw);const old=base[k]??"";if(String(old)!==String(v)){(patch[id]??={})[k]=v;changes.push({sid:id,text:nm+" · "+(SK.find(x=>x[0]===k)?.[1]||"Note")+": "+(old===""?"auto":old)+" → "+(v===""?"auto":v)})}}}
      if(Object.keys(patch).length){await J.store.patch("payroll",m,{ov:patch});for(const c of changes)await J.H.logChange(m,{type:"settlement",...c}).catch(()=>{});await new Promise(r=>setTimeout(r,300))}
      if(closed)await J.H.syncMonth(m,"monthly settlement");
      if(fd.payNow){if(!closed)return "Salaries can be paid once "+monthLabel(m)+" is over and posted.";J.derive&&J.derive();const paid={};for(const id of ids){const x=setlCalc(m,id,{});if(x.bal<=0.5||!onV(svOf(m),id))continue;const v=await J.postVoucher({type:"payment",date:fd.payDate,lines:[{a:id,dr:x.bal,cr:0,n:"Salary paid · "+monthLabel(m)},{a:fd.payFrom,dr:0,cr:x.bal,n:"Salary "+monthLabel(m)+" · "+x.s.name}],party:id,narr:"Salary settlement · "+monthLabel(m),ref:m,src:{col:"payroll",id:m,label:"Payroll"}});paid[id]=v.id}
        if(Object.keys(paid).length){await J.store.patch("payroll",m,{paid});await J.H.logChange(m,{type:"payment",text:Object.keys(paid).length+" salary payment(s) posted on "+fmtDate(fd.payDate)}).catch(()=>{})}toast(Object.keys(paid).length+" paid")}
      toast(changes.length?changes.length+" change(s) saved":"No changes")}});
  f.style.width="min(1280px,100%)";
  f.addEventListener("input",ev=>{const t=ev.target;if(!t.dataset.setl)return;const [id,k]=t.dataset.setl.split("|");(draft[id]??={})[k]=k==="adjNote"?t.value:(t.value===""?null:+t.value);
    const rows=ids.map(i=>setlCalc(m,i,draft));const fm=n=>inr.format(n||0);for(const r of rows){const set=(x,v)=>{const e=document.getElementById("sc-"+r.s.id+"-"+x);if(e)e.textContent=fm(v)};set("finalOT",r.c.finalOT);set("gross",r.c.grossPay);set("ded",r.c.ded);set("net",r.c.net);set("bal",r.bal)}
    const T=(g)=>r2(rows.reduce((t,r)=>t+g(r),0));const st=(x,v)=>{const e=document.getElementById("st-"+x);if(e)e.textContent=fm(v)};st("finalOT",T(r=>r.c.finalOT));st("gross",T(r=>r.c.grossPay));st("ded",T(r=>r.c.ded));st("net",T(r=>r.c.net));st("bal",T(r=>r.bal))})});
J.act("paySalaries",()=>{const m=WM();const due=payRows(m).filter(r=>r.posted&&!r.pv&&r.c.net>0);
  J.drawer({title:"Pay "+monthLabel(m)+" salaries",submit:"Post payments",body:`<div class="form">${fld("Pay date",dateI("date",today()))}${fld("Paid from",J.selA("from",J.MONEY,J.accsOf(["bank"])[0]?.id))}</div><table><tbody>${due.map(x=>`<tr><td><label class="row" style="gap:6px"><input type="checkbox" name="p-${x.s.id}" checked> ${esc(x.s.name)}</label></td><td class="num">${money(x.c.net)}</td></tr>`).join("")}</tbody></table><p class="hint">Each payment debits the person's salary ledger and credits the chosen account. Advance and loan recoveries are already taken out of the net pay.</p>`,
    onSubmit:async fd=>{const paid={};for(const x of due){if(!fd["p-"+x.s.id])continue;const v=await J.postVoucher({type:"payment",date:fd.date,lines:[{a:x.s.id,dr:x.c.net,cr:0,n:"Salary paid · "+monthLabel(m)},{a:fd.from,dr:0,cr:x.c.net,n:"Salary "+monthLabel(m)+" · "+x.s.name}],party:x.s.id,narr:"Salary paid · "+monthLabel(m),ref:m,src:{col:"payroll",id:m,label:"Payroll"}});paid[x.s.id]=v.id}await J.store.patch("payroll",m,{paid});toast(Object.keys(paid).length+" salary payments posted")}})});
J.openSrc.payroll=m=>{ui().wm=m;J.go("staff","payroll")};
J.act("neft",()=>{const m=WM();const run=J.get("payroll",m)||{};const rows=[["Beneficiary name","Account number","IFSC","Bank","Amount","Narration"]];const miss=[];for(const s of staff(true)){const c=calc(s,m,run.ov?.[s.id]);if(c.net<=0)continue;if(!s.bankAc||!s.ifsc)miss.push(s.name);rows.push([s.name,s.bankAc||"",s.ifsc||"",s.bankName||"",c.net.toFixed(2),"SALARY "+monthLabel(m).toUpperCase()])}
  J.saveFile("neft-salary-"+m+".csv",J.toCSV(rows));if(miss.length)toast("Bank details missing for "+miss.join(", "))});
function payslipHtml(s,m){const run=J.get("payroll",m)||{};const c=calc(s,m,run.ov?.[s.id]);const biz=J.settings().business;const row=(a,b)=>`<tr><td>${a}</td><td class="num">${b}</td></tr>`;
  return `<div class="payslip" id="slip"><div class="row" style="justify-content:space-between"><div><h3>${esc(biz)}</h3><div class="muted">Payslip for ${monthLabel(m)}</div></div><div style="text-align:right"><b>${esc(s.name)}</b><div class="muted">${esc([s.desig,s.dept].filter(Boolean).join(" · "))}</div></div></div>
  <dl class="kv" style="margin:12px 0"><dt>Days in month</dt><dd>${c.D}</dd><dt>Paid days</dt><dd>${c.paid} (P ${c.P}, Half ${c.H}, Leave ${c.L}, Week off ${c.W}${c.WW?", worked on off "+c.WW+" ×2":""}, Absent ${c.A})</dd><dt>Late marks</dt><dd>${c.late} (${c.lateMin} min)</dd><dt>PAN</dt><dd>${esc(s.pan||"—")}</dd><dt>Bank</dt><dd>${esc(s.bankName||"")} ${s.bankAc?"••"+esc(String(s.bankAc).slice(-4)):""}</dd></dl>
  <div class="grid2"><table><thead><tr><th>Earnings</th><th class="num">₹</th></tr></thead><tbody>${row("Salary for paid days (₹"+inr.format(c.perDay)+"/day)",inr.format(c.earned))}${s.sal?.basic?row("&nbsp;&nbsp;of which basic",inr.format(r2(s.sal.basic*c.paid/c.D))):""}${s.sal?.hra?row("&nbsp;&nbsp;of which HRA",inr.format(r2(s.sal.hra*c.paid/c.D))):""}${s.sal?.da?row("&nbsp;&nbsp;of which DA",inr.format(r2(s.sal.da*c.paid/c.D))):""}${c.otPay||c.shortDed||c.lateDed?row("Overtime "+c.ot+" h = ₹"+inr.format(c.otPay)+(c.shortDed?", less short duty "+c.shortH+" h ₹"+inr.format(c.shortDed):"")+(c.lateDed?", less late ₹"+inr.format(c.lateDed):"")+" → final OT",inr.format(c.finalOT)):""}${c.bonus?row("Perks / bonus",inr.format(c.bonus)):""}</tbody><tfoot><tr><td>Gross earnings</td><td class="num">${inr.format(c.grossPay)}</td></tr></tfoot></table>
  <table><thead><tr><th>Deductions</th><th class="num">₹</th></tr></thead><tbody>${c.fromSal?row("Short duty & late not covered by OT",inr.format(c.fromSal)):""}${c.penalty?row("Penalty",inr.format(c.penalty)):""}${row("Provident fund",inr.format(c.pf))}${row("ESIC",inr.format(c.esic))}${row("Professional tax",inr.format(c.pt))}${row("TDS",inr.format(c.tds))}${row("Advance recovery",inr.format(c.adv))}${c.loan||c.loanBal?row("Loan EMI",inr.format(c.loan)):""}${c.food?row("Staff food (KOT)",inr.format(c.food)):""}</tbody><tfoot><tr><td>Total deductions</td><td class="num">${inr.format(c.ded)}</td></tr></tfoot></table></div>
  <div class="row" style="justify-content:space-between;margin-top:12px;font-size:17px"><b>Net pay</b><b>${money(c.net)}</b></div>${c.advBal-c.adv>0.5?`<p class="hint">Advance balance after this month: ${money(c.advBal-c.adv)}</p>`:""}${c.loanBal-c.loan>0.5?`<p class="hint">Loan balance after this month: ${money(c.loanBal-c.loan)}</p>`:""}</div>`}
J.act("payslip",el=>{const s=J.get("accounts",el.dataset.x),m=WM();J.drawer({title:"Payslip",wide:true,body:payslipHtml(s,m)+`<div class="row"><button type="button" class="btn primary" data-a="printSlip">Print</button><button type="button" class="btn" data-a="dlSlip" data-x="${s.id}">Download payslip</button></div>`})});
J.act("dlSlip",el=>{const s=J.get("accounts",el.dataset.x),m=WM();const css="body{font-family:system-ui,sans-serif;max-width:760px;margin:24px auto;color:#18212B}table{width:100%;border-collapse:collapse}td,th{padding:6px;border-bottom:1px solid #ddd;text-align:left}.num{text-align:right}.row{display:flex;justify-content:space-between;gap:12px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.muted,.hint{color:#667}.kv{display:grid;grid-template-columns:auto 1fr;gap:4px 12px}.kv dd{margin:0}";J.saveFile("payslip-"+s.name.replace(/\W+/g,"-")+"-"+m+".html",`<!doctype html><meta charset="utf-8"><title>Payslip ${esc(s.name)} ${m}</title><style>${css}</style>`+document.getElementById("slip").outerHTML,"text/html")});

// ---------- Advances ----------
function vAdvances(){const U=ui();const m=WM();const end=J.monthEnd(m),from=m+"-01";const list=J.staffInMonth(m);
  const mv=(id)=>J.movement(id,from,end);const rows=list.map(s=>{const a=mv("adv-"+s.id),l=mv("loan-"+s.id);return {s,adv:J.balanceOf("adv-"+s.id,end),loan:J.balanceOf("loan-"+s.id,end),sal:J.balanceOf(s.id,end),aGiven:a.dr,aRec:a.cr,lGiven:l.dr,lRec:l.cr}});
  const T=k=>r2(rows.reduce((t,r)=>t+r[k],0));
  return `<div class="filters">${fld("Month",`<input type="month" id="adv-m" data-ui="staff.wm" value="${m}">`)}<span class="hint">${rows.length} staff in service in ${monthLabel(m)} · balances as at ${fmtDate(end)}</span></div>
  <div class="kpis">${J.kpi("Advances given",money0(T("aGiven")),"recovered "+money0(T("aRec")))}${J.kpi("Loans given",money0(T("lGiven")),"EMI recovered "+money0(T("lRec")))}${J.kpi("Advance balance",money0(T("adv")),"at month end")}${J.kpi("Loan balance",money0(T("loan")),"at month end")}</div>
  <div class="panel"><div class="tbl-wrap"><table><thead><tr><th>Staff</th><th class="num">Advance given</th><th class="num">Advance recovered</th><th class="num">Advance balance</th><th class="num">Loan given</th><th class="num">EMI recovered</th><th class="num">Loan balance</th><th class="num">Salary ledger</th><th></th></tr></thead><tbody>
  ${rows.length?rows.map(r=>`<tr><td>${esc(r.s.name)}<div class="hint">${esc(r.s.code||"")}${r.s.active===false?" · left":""} · recovery ${r.s.sal?.instal?money0(r.s.sal.instal):"full balance"}${r.s.sal?.loanEmi?" · EMI "+money0(r.s.sal.loanEmi):""}</div></td><td class="num">${r.aGiven?money(r.aGiven):"—"}</td><td class="num">${r.aRec?money(r.aRec):"—"}</td><td class="num">${r.adv>0.004?money(r.adv):"—"}</td><td class="num">${r.lGiven?money(r.lGiven):"—"}</td><td class="num">${r.lRec?money(r.lRec):"—"}</td><td class="num">${r.loan>0.004?money(r.loan):"—"}</td>
    <td class="num">${r.sal<-0.004?`<span class="chip bad">Due ${money(-r.sal)}</span>`:r.sal>0.004?`<span class="chip warn">Overpaid ${money(r.sal)}</span>`:"Settled"}</td>
    <td style="white-space:nowrap"><button class="btn small w" data-a="giveAdv" data-x="${r.s.id}">Advance</button> <button class="btn small w" data-a="giveLoan" data-x="${r.s.id}">Loan</button> <button class="btn small" data-a="openLedger" data-x="adv-${r.s.id}">Adv. ledger</button> <button class="btn small" data-a="openLedger" data-x="loan-${r.s.id}">Loan ledger</button> <button class="btn small" data-a="openLedger" data-x="${r.s.id}">Salary ledger</button></td></tr>`).join(""):J.emptyRow(9,"Nobody in service in "+monthLabel(m))}
  </tbody></table></div></div><p class="hint">Only staff who were in service during the selected month are listed. A new advance or loan is dated in this month (today if it is the current month). Each person has separate salary, advance and loan ledgers; recoveries come through the monthly salary entry. Perks, bonus, penalties and recovery changes for the month are entered on the Payroll tab.</p>`}
// ---------- Notebook ----------
const TAGS=["Note","Award","Reprimand","Training","Leave","Health","Uniform / kit","Exit","Joining","Increment"];
function vNotebook(){const U=ui();const all=staff(true).flatMap(s=>[...(Array.isArray(s.notes)?s.notes:[]).map((n,i)=>({...n,s,i})),...J.H.stints(s).filter(x=>x.exit&&x.exitRemarks&&x.exitRemarks!=="-").map(x=>({tag:"Exit",date:x.exit,text:x.code+" · "+(x.exitReason?x.exitReason+" · ":"")+x.exitRemarks,s,sys:1})),...J.H.stints(s).filter(x=>x.notes).map(x=>({tag:"Joining",date:x.join,text:x.code+" · "+x.notes,s,sys:1})),...J.H.revisions(s).filter(r=>r.kind==="rev"&&r.notes).map(r=>({tag:"Increment",date:r.date,text:(r.event||"Revision")+" "+J.money0(r.from||0)+" → "+J.money0(r.to||0)+" · "+r.notes,s,sys:1}))]).filter(n=>!U.tag||n.tag===U.tag).sort((a,b)=>(b.date||"").localeCompare(a.date||"")||(b.at||0)-(a.at||0));
  return `<div class="filters"><div class="seg"><button data-set="staff.tag=" aria-pressed="${!U.tag}">All</button>${TAGS.map(t=>`<button data-set="staff.tag=${t}" aria-pressed="${U.tag===t}">${t}</button>`).join("")}</div><button class="btn primary w" data-a="addNote" style="margin-left:auto">Add note</button></div>
  <div class="panel pb"><div class="timeline">${all.map(n=>`<div class="ti"><div class="row" style="gap:8px"><b>${esc(n.s.name)}</b><span class="chip ${n.tag==="Award"?"ok":n.tag==="Reprimand"?"bad":"plain"}">${esc(n.tag)}</span><small>${fmtDate(n.date)}${n.by?" · by "+esc(n.by):""}</small><span style="margin-left:auto">${n.sys?`<span class="hint">from ${n.tag==="Exit"?"exit":n.tag==="Joining"?"joining":"salary revision"} record</span>`:J.confirmBtn("n:"+n.s.id+":"+n.at,"Delete note","delNote",n.s.id+"|"+n.at)}</span></div><div>${esc(n.text)}</div></div>`).join("")||'<p class="muted">No notes yet. Record awards, warnings, training and leave here.</p>'}</div></div>`}
J.act("addNote",el=>{const pre=el.dataset.x||"";J.closeDrawer();J.drawer({title:"Add to staff notebook",submit:"Save note",body:`${fld("Staff member",staffSel("sid",pre,WM()))}<div class="form">${fld("Date",dateI("date",today()))}${fld("Type",selO("tag",TAGS,"Note"))}${fld("Recorded by",txt("by",S.me.name||""))}</div>${fld("Note",area("text","",3))}`,
  onSubmit:async fd=>{if(!fd.sid)return "Choose the staff member.";if(!fd.text.trim())return "Write the note.";const s=J.get("accounts",fd.sid);const notes=[...(Array.isArray(s.notes)?s.notes:[]),{date:fd.date,tag:fd.tag,by:fd.by,text:fd.text.trim(),at:Date.now()}];await J.store.put("accounts",{...s,notes});toast("Note saved")}})});
J.act("delNote",async el=>{const [sid,at]=el.dataset.x.split("|");const s=J.get("accounts",sid);await J.safe(()=>J.store.put("accounts",{...s,notes:(s.notes||[]).filter(n=>String(n.at)!==at)}),"Note deleted");S.confirm=null;J.render()});

J.mod({id:"staff",label:"Staff & Payroll",group:"Operations",icon:'<circle cx="9" cy="8" r="3.2"/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6"/><path d="M16 4.5a3 3 0 0 1 0 6M21 20c0-2.6-1.6-4.8-4-5.6"/>',sub:"People, attendance and payroll. Each person has a salary ledger plus separate advance and loan ledgers.",
  badge:()=>{const t=today();return staff().filter(s=>!dayStatus(s.id,t)&&!weekOff(s,t)).length&&new Date().getHours()>=11?staff().filter(s=>!dayStatus(s.id,t)&&!weekOff(s,t)).length:0},
  tabs:[["team","Team",vStaff],["attendance","Attendance",vAttendance],["empatt","Employee month",vEmpAtt],["payroll","Payroll",vPayroll],["advances","Advances",vAdvances],["notebook","Notebook",vNotebook],["policy","Policies & rules",()=>J.R.vPolicy()]]});
})();
